// --- RF-006: descuento global (docs/cambios/2026-11-11-descuento-global.md) ---
const ITEMS_DESC = [
  { cantidad: 2, precioUnitarioCentavos: 5000 },
  { cantidad: 1, precioUnitarioCentavos: 1050 },
];

test("RF-006 T1: sin descuentoGlobal el resultado es exactamente el de hoy", () => {
  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
  assert.deepEqual(calcularFactura(ITEMS_DESC), esperado);
  assert.deepEqual(calcularFactura(ITEMS_DESC, {}), esperado);
  assert.deepEqual(calcularFactura(ITEMS_DESC, { descuentoGlobal: undefined }), esperado);
});

test("RF-006 T2: descuento global del 10 %", () => {
  assert.deepEqual(calcularFactura(ITEMS_DESC, { descuentoGlobal: 10 }), {
    subtotalCentavos: 11050, descuentoCentavos: 1105, totalCentavos: 9945, ivaCentavos: 1293, netoCentavos: 8652,
  });
});

test("RF-006 T3: descuentoGlobal 0 explícito incluye los campos nuevos", () => {
  assert.deepEqual(calcularFactura(ITEMS_DESC, { descuentoGlobal: 0 }), {
    subtotalCentavos: 11050, descuentoCentavos: 0, totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613,
  });
});

test("RF-006 T4: el descuento se redondea al centavo con Math.round", () => {
  assert.deepEqual(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 999 }], { descuentoGlobal: 15 }), {
    subtotalCentavos: 999, descuentoCentavos: 150, totalCentavos: 849, ivaCentavos: 110, netoCentavos: 739,
  });
});

test("RF-006 T5: descuento del 100 % deja todo en cero y no se rechaza", () => {
  assert.deepEqual(calcularFactura(ITEMS_DESC, { descuentoGlobal: 100 }), {
    subtotalCentavos: 11050, descuentoCentavos: 11050, totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0,
  });
});

test("RF-006 T6: descuentoGlobal fuera de 0-100 o no entero lanza RangeError", () => {
  for (const invalido of [-1, 101, 10.5, "10", NaN, null, Infinity]) {
    assert.throws(() => calcularFactura(ITEMS_DESC, { descuentoGlobal: invalido }), RangeError, String(invalido));
  }
});

test("RF-006 T7: las validaciones de líneas siguen vigentes con descuento", () => {
  assert.throws(() => calcularFactura([], { descuentoGlobal: 10 }));
  assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 10.5 }], { descuentoGlobal: 10 }), RangeError);
});

test("RF-006 T8: emitirFactura no cambia de forma y sigue congelada", () => {
  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: ITEMS_DESC });
  assert.deepEqual(Object.keys(f).sort(), ["estado", "items", "ivaCentavos", "netoCentavos", "nit", "numero", "razonSocial", "totalCentavos"]);
  assert.equal(f.totalCentavos, 11050);
  assert.ok(Object.isFrozen(f));
});
